#!/usr/bin/env bash
set -Eeuo pipefail
umask 077

# ============================================================
# BasicSwap installer for Whonix Workstation (Debian 13)
#
# Downloads basicswap-bash v0.19.1, checks the exact upstream
# commit, applies the embedded Whonix patch series and checks that
# the result matches the reviewed tree exactly, then runs the
# installer. The patched installer itself only installs a BasicSwap
# release tag signed by the pinned release key.
#
# Generated by make-installer.sh from the whonix branch. Don't edit.
# ============================================================

HELPER_REPO="https://github.com/nahuhh/basicswap-bash.git"
HELPER_TAG="v0.19.1"
HELPER_COMMIT="94a86da564d3b7f08da702392c5e16c4b8879d1b"
PATCHED_TREE="18b8a97e362cf21d1f174ff2deef00370de0bc15"

HELPER_DIR="${HELPER_DIR:-$HOME/basicswap-whonix-src}"
SWAP_DATADIR="$HOME/coinswaps"

die() {
    echo "ERROR: $*" >&2
    exit 1
}

info() {
    echo
    echo "================================================"
    echo "$*"
    echo "================================================"
}

[[ "$EUID" -ne 0 ]] || die "Run as your ordinary user, not root."

# An earlier install, or one that stopped part way (e.g. a Tor network error), must be
# removed first: the upstream installer won't overwrite it
existing=()
for dir in "$HELPER_DIR" "$SWAP_DATADIR"; do
    [[ -e "$dir" ]] && existing+=("$dir")
done
if (( ${#existing[@]} )); then
    if pgrep -f "$SWAP_DATADIR/(bin|venv)/" > /dev/null; then
        die "BasicSwap is running from $SWAP_DATADIR. Stop it (Ctrl+C in its terminal) and run this again."
    fi
    echo "An earlier BasicSwap install was found:"
    printf '  %s\n' "${existing[@]}"
    if [[ -e "$SWAP_DATADIR/basicswap.json" ]]; then
        echo
        echo "****************************************************************"
        echo "WARNING: $SWAP_DATADIR contains BasicSwap wallets. Removing it"
        echo "deletes them. Funds in them can only be recovered with their"
        echo "recovery phrase (seed). Don't continue unless the wallets are"
        echo "unused, or you have the seed and know the funds are recoverable."
        echo "****************************************************************"
    fi
    echo
    echo "To remove these and install again, type exactly: YES I WANT TO REMOVE"
    read -r -p "Anything else exits without changes: " answer
    [[ "$answer" == "YES I WANT TO REMOVE" ]] || { echo "Nothing removed."; exit 1; }
    rm -rf -- "${existing[@]}"
    echo "Removed."
fi
[[ -f /etc/os-release ]] || die "Cannot identify the operating system."

# Whonix may rename the distribution in os-release, but keeps Debian's debian_version
source /etc/os-release
debian_version=$(cat /etc/debian_version 2> /dev/null || true)
[[ "${ID:-}" == "debian" || " ${ID_LIKE:-} " == *" debian "* || -n "$debian_version" ]] &&
    [[ "${VERSION_CODENAME:-}" == "trixie" || "$debian_version" == 13* || "$debian_version" == trixie* ]] ||
    die "This installer requires Debian 13 (trixie) / Whonix 18."

if [[ ! -e /usr/share/whonix/marker ]]; then
    echo "WARNING: This doesn't look like a Whonix Workstation."
    echo "BasicSwap will run without Tor and connect directly."
    read -rp "Continue anyway? [y/N] " answer
    [[ "$answer" =~ ^[yY]$ ]] || exit 1
fi

# ------------------------------------------------------------
# Dependencies. Whonix AppVMs have no sudo, and packages installed in an
# AppVM are lost on reboot, so they must come from the template.
# Keep in sync with setup-whonix-template.sh
# ------------------------------------------------------------

PACKAGES=(jq gnupg git curl python3-venv libpython3-dev gcc libc6-dev)
missing=()
for pkg in "${PACKAGES[@]}"; do
    dpkg-query -W -f='${db:Status-Abbrev}' "$pkg" 2> /dev/null | grep -q '^ii' || missing+=("$pkg")
done
if (( ${#missing[@]} )); then
    echo "Missing packages: ${missing[*]}" >&2
    echo "Run setup-whonix-template.sh in the Whonix Workstation template," >&2
    echo "shut the template down, then restart this AppVM." >&2
    die "Dependencies missing."
fi

# ------------------------------------------------------------
# Download the pinned helper scripts
# ------------------------------------------------------------

info "Downloading basicswap-bash $HELPER_TAG"

# Tor circuits sometimes fail briefly, so retry
for try in 1 2 3 4; do
    git -c advice.detachedHead=false clone --quiet --depth 1 --branch "$HELPER_TAG" "$HELPER_REPO" "$HELPER_DIR" && break
    rm -rf "$HELPER_DIR"
    [[ $try -lt 4 ]] || die "Could not download basicswap-bash. Check the Whonix connection and run again."
    echo "Attempt $try/4 failed. Tor may be busy; retrying in 15 seconds.."
    sleep 15
done

actual=$(git -C "$HELPER_DIR" rev-parse HEAD)
[[ "$actual" == "$HELPER_COMMIT" ]] ||
    die "basicswap-bash $HELPER_TAG is $actual, expected $HELPER_COMMIT."
echo "basicswap-bash $HELPER_TAG: $actual"

# ------------------------------------------------------------
# Apply the Whonix patch series
# ------------------------------------------------------------

info "Applying Whonix patches"

sed -n "/^: <<'__WHONIX_PATCHES__'\$/,/^__WHONIX_PATCHES__\$/p" "${BASH_SOURCE[0]}" | sed '1d;$d' |
    git -C "$HELPER_DIR" -c user.name=whonix -c user.email=whonix@localhost \
        am --quiet --whitespace=nowarn ||
    die "The Whonix patches don't apply to basicswap-bash $HELPER_TAG."

actual=$(git -C "$HELPER_DIR" rev-parse 'HEAD^{tree}')
[[ "$actual" == "$PATCHED_TREE" ]] ||
    die "Patched files don't match the reviewed version (tree $actual)."

git -C "$HELPER_DIR" log --format='  %s' "$HELPER_COMMIT..HEAD"
echo "Original files: git -C $HELPER_DIR diff $HELPER_TAG"

# ------------------------------------------------------------
# Run the patched upstream installer
# ------------------------------------------------------------

info "Starting the BasicSwap installer"

cd "$HELPER_DIR"
if ! ./basicswap-install.sh "$@"; then
    echo >&2
    echo "The install stopped part way. Network errors over Tor are usually temporary." >&2
    echo "Run this script again; it offers to remove the partial install first." >&2
    echo "In Whonix, a new Tor circuit can help (Tor Control Panel on the Gateway: New Identity)." >&2
    die "The BasicSwap installer failed."
fi

# ------------------------------------------------------------
# Final checks
# ------------------------------------------------------------

info "Checking the installation"

CONFIG="$SWAP_DATADIR/basicswap.json"
[[ -f "$CONFIG" ]] || die "BasicSwap configuration not found: $CONFIG"
[[ "$(jq -r '.use_tor' "$CONFIG")" != "true" ]] || die "BasicSwap Tor is enabled."

tag=$(git -C "$SWAP_DATADIR/basicswap" describe --tags --exact-match) ||
    die "BasicSwap isn't checked out at a release tag."
# shared.sh isn't written for set -u, so check in a clean shell
bash -c 'cd "$1" && source "$2/bsx/shared.sh" && verify_core_release "$3"' _ \
    "$SWAP_DATADIR/basicswap" "$HELPER_DIR" "$tag" ||
    die "BasicSwap release verification failed."

echo
echo "basicswap-bash: $HELPER_TAG + Whonix patches ($HELPER_DIR)"
echo "BasicSwap:      $tag"
echo "use_tor:        $(jq -r '.use_tor' "$CONFIG")"
echo
echo "Automatic updates are disabled. See $HELPER_DIR/WHONIX.md"
echo
cat << 'EOF'

================================================
Next steps
================================================

0. BACKUP. The Particl recovery phrase shown during the install is the
   backup for ALL your BasicSwap wallets, including Monero: BasicSwap
   creates the Monero wallet from it, so there is no separate Monero seed.
   Write it down with the Monero restore height, even if you don't care
   about Particl. 'bsx-xmrkeys' shows the Monero keys if you need them.

1. Start BasicSwap. Open a NEW terminal (this one doesn't have the new
   commands yet) and run:
       basicswap-bash
   or run it now with: ~/.local/bin/basicswap-bash
   Leave it running. To stop BasicSwap and all its coin daemons, press
   Ctrl+C in that terminal and wait for it to finish (up to a few minutes).

2. Monero sync. If BasicSwap runs its own Monero node, watch it download
   blocks in another terminal (Ctrl+C stops watching only):
       bsx-xmrsync
   The full download is about 90 GB and takes a long time over Tor.

3. Open the web UI in Tor Browser in THIS qube:
   a. Open the address: about:config   and accept the warning.
   b. Search for: network.proxy.allow_hijacking_localhost
   c. Double-click it so it shows: false
   d. Open: http://127.0.0.1:12700

   ****************************************************************
   WARNING: After this change, use this qube's Tor Browser ONLY for
   BasicSwap. Any website you open in it can send requests to
   BasicSwap and can tell that you run it, which identifies you.
   Browse the web in a different Whonix qube.
   ****************************************************************

   Also set a web UI password: bsx-clientauth
   Safer setups (an offline UI qube, or Firefox locked to BasicSwap) are
   in the README.md that comes with this installer, "Using the web UI".

EOF
exit 0

# Whonix patch series, applied with git am above
