         exit
     fi
 }
+
+# Whonix: verify a signed BasicSwap release tag and check it out
+# Run from inside the basicswap git checkout
+verify_core_release() {
+    local tag="$1" gnupg verify signer primary
+    if [[ ! "$tag" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
+        red "Invalid BasicSwap release tag: $tag"
+        return 1
+    fi
+    if ! git show-ref --verify --quiet "refs/tags/$tag"; then
+        red "BasicSwap release tag $tag not found"
+        return 1
+    fi
+    if [[ $(git cat-file -t "refs/tags/$tag") != tag ]]; then
+        red "BasicSwap release tag $tag is not an annotated tag"
+        return 1
+    fi
+    # The name inside the signed tag must match, otherwise an older release could be renamed
+    if [[ $(git cat-file tag "$tag" | sed -n 's/^tag //p') != "$tag" ]]; then
+        red "BasicSwap release tag $tag was signed under a different name"
+        return 1
+    fi
+
+    # Isolated keyring holding only the BasicSwap release key
+    gnupg=$(mktemp -d) || return 1
+    GNUPGHOME="$gnupg" gpg --batch --quiet --import "$BSX_CORE_SIGNING_KEY" 2> /dev/null
+    verify=$(GNUPGHOME="$gnupg" git verify-tag --raw "$tag" 2>&1)
+    rm -rf "$gnupg"
+    read -r signer primary <<< "$(awk '$1 == "[GNUPG:]" && $2 == "VALIDSIG" {print toupper($3), toupper($NF); exit}' <<< "$verify")"
+    if ! grep -q '^\[GNUPG:\] GOODSIG ' <<< "$verify" || [[ "$primary" != "$BSX_CORE_SIGNING_FPR" ]]; then
+        echo "$verify"
+        red "BasicSwap release $tag is not signed by $BSX_CORE_SIGNING_FPR"
+        return 1
+    fi
+    green "BasicSwap release $tag signed by $primary"
+
+    git -c advice.detachedHead=false checkout --quiet --detach "$tag" || return 1
+    if [[ $(git rev-parse HEAD) != $(git rev-parse "$tag^{commit}") ]]; then
+        red "BasicSwap checkout does not match release $tag"
+        return 1
+    fi
+    if [[ $(git status --porcelain --untracked-files=no) ]]; then
+        red "BasicSwap checkout has local modifications"
+        return 1
+    fi
+}

From bf7fbb20306b69c9ff80f32cb57e5cd888132777 Mon Sep 17 00:00:00 2001
From: BasicSwap Whonix <whonix@localhost>
Date: Fri, 20 Nov 2026 22:08:07 -0500
Subject: [PATCH 02/20] whonix: install only the verified BasicSwap release

Replace the unverified git pull / clone of master with the signed
BSX_CORE_TAG release, abort when pip fails, and pass the Particl mnemonic
to basicswap-prepare on stdin instead of the command line.
---
 bsx/setup.sh | 63 +++++++++++++++++++++++++++++++++++++++-------------
 1 file changed, 48 insertions(+), 15 deletions(-)

diff --git a/bsx/setup.sh b/bsx/setup.sh
index 69cc0f6..4bc2506 100755
--- a/bsx/setup.sh
+++ b/bsx/setup.sh
@@ -2,20 +2,25 @@
 source $HOME/.local/bin/bsx/shared.sh
 
 ## Clone basicswap git
+# Whonix: only install a signed release tag, verified against the pinned release key
 cd $SWAP_DATADIR
-if [[ -d basicswap ]]; then
-    cd $SWAP_DATADIR/basicswap
-    git pull || {
-        red "Failed to pull repo. Installation aborted"
-        exit 1
-    }
-else
+if [[ ! -d basicswap ]]; then
     git clone https://github.com/basicswap/basicswap || {
         red "Failed to clone repo. Please run the installer again"
         exit 1
     }
-    cd $SWAP_DATADIR/basicswap
 fi
+cd $SWAP_DATADIR/basicswap
+if ! git show-ref --verify --quiet "refs/tags/$BSX_CORE_TAG"; then
+    git fetch --tags origin || {
+        red "Failed to fetch release tags. Installation aborted"
+        exit 1
+    }
+fi
+verify_core_release "$BSX_CORE_TAG" || {
+    red "BasicSwap release verification failed. Installation aborted"
+    exit 1
+}
 
 ## Install basicswap, coincurve, and pip dependencies
 
@@ -26,14 +31,32 @@ if [[ "${TAILS}" ]]; then
         exit 1
     }
 else
-    $SWAP_DATADIR/venv/bin/pip3 install -r requirements.txt --require-hashes
-    $SWAP_DATADIR/venv/bin/pip3 install .
+    $SWAP_DATADIR/venv/bin/pip3 install -r requirements.txt --require-hashes \
+        && $SWAP_DATADIR/venv/bin/pip3 install . || {
+        red "Installation failed"
+        exit 1
