From 50063bd328cf57e6bcba203f8833a68cc6400307 Mon Sep 17 00:00:00 2001
From: BasicSwap Whonix <whonix@localhost>
Date: Sat, 21 Nov 2026 01:01:47 -0500
Subject: [PATCH 09/20] whonix: skip apt when the Qubes template provides the
 dependencies

Packages installed in a Qubes AppVM outside /home are lost on reboot, so
they belong in the template. Use real package names so they can be
detected.
---
 basicswap-install.sh | 9 ++++++++-
 bsx/shared.sh        | 5 +++--
 2 files changed, 11 insertions(+), 3 deletions(-)

diff --git a/basicswap-install.sh b/basicswap-install.sh
index a4ba97f..5c3604e 100755
--- a/basicswap-install.sh
+++ b/basicswap-install.sh
@@ -48,7 +48,14 @@ detect_os_arch
 echo -e "\n\nInstalling dependencies\nPress CTRL-C at password prompt(s) to skip. If skipped, you must install the dependencies manually before proceeding\n"
 green "$UPDATE\n$INSTALL curl automake libtool jq ${DEPENDENCY}"
 
-$UPDATE && $INSTALL curl automake libtool jq $DEPENDENCY || echo -e "Skipping dependency installation"
+# Whonix: skip apt when the template already provides everything. In a Qubes AppVM,
+# packages installed outside /home are lost on reboot
+deps="curl automake libtool jq ${DEPENDENCY/--no-install-recommends/}"
+if [[ $DEBIAN ]] && [[ $(dpkg-query -W -f='${db:Status-Abbrev}\n' $deps 2> /dev/null | grep -c '^ii') -eq $(wc -w <<< "$deps") ]]; then
+    green "Dependencies already installed"
+else
+    $UPDATE && $INSTALL curl automake libtool jq $DEPENDENCY || echo -e "Skipping dependency installation"
+fi
 ${PIPX_UV:-}
 
 # Enable tor
diff --git a/bsx/shared.sh b/bsx/shared.sh
index cb2fc59..77d1012 100755
--- a/bsx/shared.sh
+++ b/bsx/shared.sh
@@ -226,8 +226,9 @@ detect_os_arch() {
         fi
         INSTALL="sudo apt install -y"
         UPDATE="sudo apt update"
-        # Whonix: use the system Python. Don't install uv from PyPI unverified
-        DEPENDENCY="python3-venv libpython3-dev gnupg pkg-config gcc libc-dev --no-install-recommends"
+        # Whonix: use the system Python. Don't install uv from PyPI unverified.
+        # Real package names (not pkg-config/libc-dev) so installed packages can be detected
+        DEPENDENCY="python3-venv libpython3-dev gnupg pkgconf gcc libc6-dev --no-install-recommends"
     else
         red "\nFailed to detect OS. Unsupported or unknown distribution.\nInstall Failed."
         exit

From b21817009779e30c1cc80424741bca0a42316850 Mon Sep 17 00:00:00 2001
From: BasicSwap Whonix <whonix@localhost>
Date: Sat, 21 Nov 2026 01:06:19 -0500
Subject: [PATCH 10/20] whonix: detect Debian before Fedora and Arch

A Debian system with dnf installed was detected as Fedora, so the
dependency step ran dnf instead of apt.
---
 WHONIX.md     | 2 ++
 bsx/shared.sh | 5 +++--
 2 files changed, 5 insertions(+), 2 deletions(-)

diff --git a/WHONIX.md b/WHONIX.md
index 08671f9..65fe858 100644
--- a/WHONIX.md
+++ b/WHONIX.md
@@ -12,6 +12,8 @@ Every change is marked with a `# Whonix:` comment, and `git log v0.19.1..whonix`
 | `setup.sh` runs `git pull` / clones `master` of BasicSwap | Installs only the signed release tag `BSX_CORE_TAG` (default `v0.19.2`), verified against the pinned key `62C74C113CD9E31DAA65564F8ED6D8750C4E3F93` shipped in `bsx/keys/` |
 | `bsx-update` runs `git pull` on both repositories | Disabled. Use the manual procedure below |
 | pip failures are ignored outside Tails | pip failures abort the install |
+| Detects Fedora or Arch on Debian systems that have `dnf` or `pacman` installed | Debian is detected first |
+| Always runs `sudo apt install` | Skipped when the Qubes template already provides the packages (`setup-whonix-template.sh`) |
 | `pipx install uv`, and uv may download a Python build | uv isn't installed, and `UV_PYTHON_DOWNLOADS=never`. The system Python 3.13 is used |
 | Particl seed is shown while typed and printed back | Input is hidden and never printed |
 | Particl seed is passed on the `basicswap-prepare` command line (visible in `ps`) | Passed on stdin with `--particl_mnemonic` (requires BasicSwap >= v0.19.1) |
diff --git a/bsx/shared.sh b/bsx/shared.sh
index 77d1012..95dcddb 100755
--- a/bsx/shared.sh
+++ b/bsx/shared.sh
@@ -201,14 +201,15 @@ detect_os_arch() {
         fi
         DEPENDENCY="python gnupg pkg-config coreutils zeromq"
         green "\n\nDetected MacOS"
-    elif type -p dnf > /dev/null; then
+    # Whonix: a Debian system can have dnf or pacman installed, so check for Debian first
+    elif type -p dnf > /dev/null && [[ ! -f /etc/debian_version ]]; then
         # Fedora
         FEDORA=1
         INSTALL="sudo dnf install -y"
         UPDATE="sudo dnf update -y"
         DEPENDENCY="python3-virtualenv python3-pip python3-devel gnupg2 pkgconf"
         green "\n\nDetected Fedora"
-    elif type -p pacman > /dev/null; then
+    elif type -p pacman > /dev/null && [[ ! -f /etc/debian_version ]]; then
         # Arch Linux
         ARCH=1
         INSTALL="sudo pacman -S --noconfirm --needed"

