From 7369878a21731c264f1cd9ad4d62a1951b65229b Mon Sep 17 00:00:00 2001
From: BasicSwap Whonix <whonix@localhost>
Date: Sun, 22 Nov 2026 02:46:52 -0500
Subject: [PATCH 15/20] whonix: clearer Monero remote node option

Default port, a 60 second check for Tor and onion nodes, the RPC password
passed to curl on stdin, and nodes the user doesn't run set as untrusted.
That is set in basicswap.json because basicswap-prepare parses
--trustremotenode=false as true.

Co-Authored-By: Claude <noreply@anthropic.com>
---
 WHONIX.md            |  1 +
 basicswap-install.sh | 32 ++++++++++++++++++++++++++++----
 bsx/setup.sh         | 10 ++++++++++
 3 files changed, 39 insertions(+), 4 deletions(-)

diff --git a/WHONIX.md b/WHONIX.md
index 008aa6f..96a7373 100644
--- a/WHONIX.md
+++ b/WHONIX.md
@@ -18,6 +18,7 @@ Every change is marked with a `# Whonix:` comment, and `git log v0.19.1..whonix`
 | `pipx install uv`, and uv may download a Python build | uv isn't installed, and `UV_PYTHON_DOWNLOADS=never`. The system Python 3.13 is used |
 | Particl seed is shown while typed and printed back | Input is hidden and never printed |
 | Particl seed is passed on the `basicswap-prepare` command line (visible in `ps`) | Passed on stdin with `--particl_mnemonic` (requires BasicSwap >= v0.19.1) |
+| Monero remote node option: 15 s check, node always trusted, RPC password on the `curl` command line | Clearer option, default port, 60 s check for Tor/onion, nodes you don't run are set `trusted_daemon = false`, password passed to `curl` on stdin |
 | `bsx-clientauth` passes the web UI password on the command line (visible in `ps`) | Passed on stdin with `--client-auth-password` |
 | `bsx-placeorder` runs the typed amount through `python3 -c` and puts unchecked input into the order JSON | Numeric input only; the amount comparison uses awk |
 
diff --git a/basicswap-install.sh b/basicswap-install.sh
index 277e35e..4f17334 100755
--- a/basicswap-install.sh
+++ b/basicswap-install.sh
@@ -173,7 +173,8 @@ until [[ "$wownero" =~ ^[12]$ ]]; do
 done
 
 ## Configure Monero
-echo -e "\n[1] Connect to a Monero node\n[2] Allow BasicSwapDEX to run a Monero node (+90GB)"
+# Whonix: make the remote node option clearer
+echo -e "\n[1] Use a remote Monero node (no blockchain download)\n[2] Allow BasicSwapDEX to run a Monero node (+90GB)"
 until [[ "$node" =~ ^[12]$ ]]; do
     if [[ "$1 $2 $3 $4" == *"internal"* ]]; then
         node=2
@@ -182,9 +183,15 @@ until [[ "$node" =~ ^[12]$ ]]; do
     fi
     case $node in
         1)
+            echo -e "\nYour own node is best. A public node works too; prefer a .onion address."
+            echo "The node sees your wallet's requests and transactions. Whonix hides your IP."
             until [[ $checknode ]]; do
-                read -p 'Enter Address of Monero node [example: 192.168.1.123] ' monerod_addr
-                read -p 'Enter RPC Port for the Monero node [example: 18081] ' monerod_port
+                monerod_addr=""
+                until [[ $monerod_addr =~ ^[A-Za-z0-9.-]+$ ]]; do
+                    read -p 'Enter Address of Monero node [example: 192.168.1.123 or xxxx.onion] ' monerod_addr
+                done
+                read -p 'Enter RPC Port for the Monero node [default: 18081] ' monerod_port
+                monerod_port=${monerod_port:-18081}
                 read -p $'\nDoes this Monero node require authentication? [y/N] ' xmr_pass
 
                 if [[ "${xmr_pass}" =~ ^[yY]$ ]]; then
@@ -198,7 +205,18 @@ until [[ "$node" =~ ^[12]$ ]]; do
                     done
                 fi
 
-                checknode=$(timeout 15s curl -sk ${monerod_user:+-u $monerod_user:$monerod_pass --digest} http://$monerod_addr:$monerod_port/get_info | jq .height)
+                # Whonix: longer timeout for Tor and onion services. Credentials go to curl
+                # on stdin, not the command line where the process list shows them
+                green "Checking the node (up to 60 seconds over Tor)..."
+                curl_auth=""
+                if [[ $monerod_user ]]; then
+                    curl_auth="$monerod_user:$monerod_pass"
+                    curl_auth=${curl_auth//\\/\\\\}
+                    curl_auth="user = \"${curl_auth//\"/\\\"}\""
+                fi
+                checknode=$(printf '%s' "$curl_auth" \
+                    | timeout 60s curl -sk --config - ${monerod_user:+--digest} "http://$monerod_addr:$monerod_port/get_info" \
+                    | jq -e '.height // empty' 2> /dev/null)
                 if [[ $checknode ]]; then
                     green "\nSuccessfully connected to the XMR node @ $monerod_addr:$monerod_port"
                 else
@@ -206,6 +224,11 @@ until [[ "$node" =~ ^[12]$ ]]; do
                 fi
 
             done
+            read -p $'\nDo you run this node yourself? [y/N] ' own_node
+            if [[ ! "${own_node}" =~ ^[yY]$ ]]; then
+                xmr_untrusted=1
+                green "The wallet won't trust this node"
+            fi
             if [[ -z $xmrrestoreheight ]]; then
                 xmrrestoreheight="${checknode}"
             fi
@@ -277,6 +300,7 @@ export monerod_pass="${monerod_pass}"
 export particl_mnemonic="${particl_mnemonic}"
 export xmrrestoreheight="${xmrrestoreheight}"
 export tor_on="${tor_on}"
+export xmr_untrusted="${xmr_untrusted}"
 export TAILS="${TAILS}"
 export MACOS="${MACOS}"
 
diff --git a/bsx/setup.sh b/bsx/setup.sh
index a3a1874..de76ac9 100755
--- a/bsx/setup.sh
+++ b/bsx/setup.sh
@@ -80,6 +80,16 @@ done
 restored=${mnemonic:+1}
 unset mnemonic
 
+# Whonix: don't trust a Monero node the user doesn't run. Set in the config because
+# basicswap-prepare --trustremotenode=false is parsed as true
+if [[ $xmr_untrusted ]]; then
+    jq '.chainclients.monero.trusted_daemon = false' $SWAP_DATADIR/basicswap.json > $SWAP_DATADIR/basicswap.json.tmp \
