From: BasicSwap Whonix <whonix@localhost>
Date: Mon, 23 Nov 2026 00:37:21 -0500
Subject: [PATCH 16/20] whonix: add bsx-xmrsync to show Monero sync progress

Co-Authored-By: Claude <noreply@anthropic.com>
---
 WHONIX.md   |  1 +
 bsx-xmrsync | 41 +++++++++++++++++++++++++++++++++++++++++
 2 files changed, 42 insertions(+)
 create mode 100755 bsx-xmrsync

diff --git a/WHONIX.md b/WHONIX.md
index 96a7373..4a46f98 100644
--- a/WHONIX.md
+++ b/WHONIX.md
@@ -19,6 +19,7 @@ Every change is marked with a `# Whonix:` comment, and `git log v0.19.1..whonix`
 | Particl seed is shown while typed and printed back | Input is hidden and never printed |
 | Particl seed is passed on the `basicswap-prepare` command line (visible in `ps`) | Passed on stdin with `--particl_mnemonic` (requires BasicSwap >= v0.19.1) |
 | Monero remote node option: 15 s check, node always trusted, RPC password on the `curl` command line | Clearer option, default port, 60 s check for Tor/onion, nodes you don't run are set `trusted_daemon = false`, password passed to `curl` on stdin |
+| No way to see the Monero node's sync progress | `bsx-xmrsync` follows the node's log and shows `Synced <downloaded>/<height>` lines (or the remote node's height) |
 | `bsx-clientauth` passes the web UI password on the command line (visible in `ps`) | Passed on stdin with `--client-auth-password` |
 | `bsx-placeorder` runs the typed amount through `python3 -c` and puts unchecked input into the order JSON | Numeric input only; the amount comparison uses awk |
 
diff --git a/bsx-xmrsync b/bsx-xmrsync
new file mode 100755
index 0000000..1cab064
--- /dev/null
+++ b/bsx-xmrsync
@@ -0,0 +1,41 @@
+#!/bin/bash
+source $HOME/.local/bin/bsx/shared.sh
+
+# Whonix: show the Monero node's sync progress. Read-only; BasicSwap keeps running
+
+is_tails
+config="$SWAP_DATADIR/basicswap.json"
+if [[ ! -f $config ]]; then
+    red "BasicSwap isn't installed: $config not found"
+    exit 1
+fi
+
+if [[ $(jq -r '.chainclients.monero.manage_daemon' "$config") = false ]]; then
+    host=$(jq -r '.chainclients.monero.rpchost' "$config")
+    port=$(jq -r '.chainclients.monero.rpcport' "$config")
+    green "Monero uses the remote node $host:$port. Nothing is downloaded here."
+    height=$(timeout 60s curl -s "http://$host:$port/get_info" | jq -r '.height // empty')
+    if [[ $height ]]; then
+        green "Remote node height: $height"
+    else
+        red "The remote node isn't reachable"
+    fi
+    exit
+fi
+
+datadir=$(jq -r '.chainclients.monero.datadir' "$config")
+log="$datadir/bitmonero.log"
+[[ -f $log ]] || log="$datadir/core_stdout.log"
+if ! pgrep -x monerod > /dev/null; then
+    red "The Monero node isn't running. Start BasicSwap with 'basicswap-bash' first."
+    exit 1
+fi
+
+green "Watching Monero sync progress. Ctrl+C stops watching; BasicSwap keeps running."
+echo "Lines look like: Synced <downloaded>/<network height> (<percent>%, <blocks> left)"
+echo "No lines yet means the node is still finding peers. This can take minutes over Tor."
+echo
+tail -n 500 -F "$log" 2> /dev/null \
+    | sed -u 's/\x1b\[[0-9;]*m//g' \
+    | grep --line-buffered -E 'Synced [0-9]+/[0-9]+|You are now synchronized|SYNCHRONIZED OK' \
+    | sed -u -E 's/^([0-9-]+ [0-9:]+)\.[0-9]+\s.*\s(Synced .*|You are now synchronized.*|.*SYNCHRONIZED OK.*)$/\1  \2/'

From b5bf98b0540d0aceec8c5f21dfb7e085a9c499c8 Mon Sep 17 00:00:00 2001
From: BasicSwap Whonix <whonix@localhost>
Date: Mon, 23 Nov 2026 01:06:44 -0500
Subject: [PATCH 17/20] whonix: retry git downloads; Tor circuits sometimes
 fail briefly

Co-Authored-By: Claude <noreply@anthropic.com>
---
 bsx/setup.sh  |  4 ++--
 bsx/shared.sh | 12 ++++++++++++
 2 files changed, 14 insertions(+), 2 deletions(-)

