index de76ac9..0fb27b9 100755
--- a/bsx/setup.sh
+++ b/bsx/setup.sh
@@ -5,14 +5,14 @@ source $HOME/.local/bin/bsx/shared.sh
 # Whonix: only install a signed release tag, verified against the pinned release key
 cd $SWAP_DATADIR
 if [[ ! -d basicswap ]]; then
-    git clone https://github.com/basicswap/basicswap || {
+    retry git clone https://github.com/basicswap/basicswap || {
         red "Failed to clone repo. Please run the installer again"
         exit 1
     }
 fi
 cd $SWAP_DATADIR/basicswap
 if ! git show-ref --verify --quiet "refs/tags/$BSX_CORE_TAG"; then
-    git fetch --tags origin || {
+    retry git fetch --tags origin || {
         red "Failed to fetch release tags. Installation aborted"
         exit 1
     }
diff --git a/bsx/shared.sh b/bsx/shared.sh
index 562de13..1b6e8eb 100755
--- a/bsx/shared.sh
+++ b/bsx/shared.sh
@@ -237,6 +237,18 @@ detect_os_arch() {
     fi
 }
 
+# Whonix: retry a network command. Tor circuits sometimes fail briefly
+retry() {
+    local tries
+    for tries in 1 2 3 4; do
+        "$@" && return 0
+        [[ $tries -lt 4 ]] || break
+        red "Attempt ${tries}/4 failed. Tor may be busy; retrying in 15 seconds.."
+        sleep 15
+    done
+    return 1
+}
+
 # Whonix: verify a signed BasicSwap release tag and check it out
 # Run from inside the basicswap git checkout
 verify_core_release() {

